// Static catalog for the standalone Vercel storefront.
// Generated 2026-11-09 from the live Hermes store (getStorefront): 416 products
// with the verified per-product data (ref codes, colours, gallery views, sizes,
// detail lines, descriptions). Photos are NOT bundled here — see placeholders.ts.
// Settings are the live store settings at generation time; admin edits are kept
// in localStorage on top of these defaults (see api.ts).

export type ProductColor = { name: string; hex: string; available: boolean; pdpName?: string };
export type SizeOption = { label: string; available: boolean };

export type Product = {
  id: number; name: string; category: string; subcategory: string;
  theme: string; line: string; madeIn?: string; material: string; modelSize: string;
  metallicFinish: string; colors: ProductColor[];
  price: number; priceLabel: string; status: string; description: string;
  story: string; tone: string; glyph: string; sortOrder: number; fwPos?: number; ssPos?: number;
  refCode: string; galleryViews: string[]; applePay: boolean; configUrl?: string;
  sizeOptions: SizeOption[]; accordions: string[]; shippingDelay: string;
  detailLines: string[];
  // Per-product overrides (optional; only the Cashmere coat uses them so far):
  // colorwayRefs — refCodes of sibling colourway rows (PDP colour thumbs navigate to them);
  // partnerIds / exploreIds — exact "The Perfect Partner" / "Keep exploring" rows;
  // accordionBodies — verbatim accordion bodies; lines starting "## " are subheadings,
  // lines starting "• " are bullets; defaultSize — size pre-selected on landing.
  colorwayRefs?: string[]; partnerIds?: number[]; exploreIds?: number[]; partnerFeature?: boolean;
  accordionBodies?: Record<string, string[]>; defaultSize?: string;
  // fineSub — finer subcategory inside a broad subcategory (used by Small
  // leather goods: "To Go wallets" / "Wallets" / "Card holders" /
  // "Pouches and cases" / "Customizable"). The parent subcategory stays
  // "Small leather goods" so the parent page still lists every row.
  // Also used by men's RTW sub-pages ("Coats and parkas" / "Jackets and
  // blazers" / "Knitwear" / "Shirts" / "T-shirts and sweatshirts" /
  // "Pants and shorts" / "Beachwear") — the rows keep their own
  // subcategory/line, and the sub-page order is carried by subPos.
  fineSub?: string;
  // subPos — position within a subcategory page (men's RTW sub-pages,
  // 2026-11-15). The collection pages use fwPos/ssPos; the sub-pages
  // have their own order, so they sort by subPos instead.
  subPos?: number;
  // slgPos — position within an SLG subcategory page (dedicated page
  // order, 2026-11-15). The SLG parent page has its own order and does
  // not sort by slgPos.
  slgPos?: number;
  // slgParentPos — position within the SLG PARENT page
  // (/us/en/category/leather/small-leather-goods/, 2026-11-15).
  // The parent has its own live order (354 tiles); the two slgPos
  // rows not on the parent page (id1380, id1427) carry no slgParentPos
  // and are excluded from the parent grid by the syn.
  slgParentPos?: number;
  scarfPos?: number;
  beltPos?: number;
  dressPos?: number;
  // jewPos — position within the fine-jewelry page (/jewelry/, rings
  // first, 2026-11-15). The /jewelry/ page and its sub-pages sort by
  // jewPos.
  jewPos?: number;
  // fashPos — position within the fashion-jewelry page
  // (/women/fashion-jewelry/, 2026-11-15). The fashion page and its
  // sub-pages sort by fashPos; rows without one (removed from the
  // original) sort last.
  fashPos?: number;
  // homePos — position within the Home page (/home/, 2026-11-15).
  // Only the 41 new rows and the 8 dual-listed cases/mirror rows
  // carry one; the 1,192 older Home rows keep their existing order
  // (the original's live grid order has drifted since the 1,255
  // list was taken, so homePos is best-effort, not live-exact).
  homePos?: number;
  // shoePos — position within the Women's Shoes page
  // (/us/en/category/women/shoes/, 2026-11-15). All 689 rows on the
  // original's list carry one (613 matched + 7 size-suffix + 69 new);
  // the 12 clone shoe rows not on the original sort last.
  shoePos?: number;
  // menShoePos — position within the Men's Shoes page
  // (/us/en/category/men/shoes/, 2026-11-15). All 328 rows on the
  // original's list carry one (276 matched + 10 duplicate-ref picks +
  // 42 new); the 50 clone shoe rows not on the original sort last.
  menShoePos?: number;
  // wBagPos — position within the Women's Bags parent page
  // (/us/en/category/leather-goods/bags-and-clutches/womens-bags-and-clutches/,
  // 2026-11-15). All 45 rows on the original's list carry one (26 matched
  // women rows + 11 leather rows + 4 men rows + 4 new); the 5 clone bag
  // rows not on the original sort last.
  wBagPos?: number;
  // mBagPos — position within the Men's Bags parent page
  // (/us/en/category/leather-goods/bags-and-clutches/mens-bags-and-clutches/,
  // 2026-11-15). All 104 rows on the original's list carry one (62 matched
  // men/leather rows + 5 women rows + 37 new); the 19 clone bag rows not
  // on the original sort last.
  mBagPos?: number;
  // Watches parent page (2026-11-15) — the original's live order (370
  // tiles) lives in watchPos; the parent lists exactly those rows.
  watchPos?: number;
  // Fragrances parent page (2026-11-15) — the original's live order (272
  // tiles) lives in fragPos; the parent lists exactly those rows.
  fragPos?: number;
  // tabPos — position within the Tableware page
  // (/us/en/category/home/tableware/, 2026-11-15). The Tableware
  // parent lists exactly those rows; the rows also carry homePos
  // for the Home parent page.
  tabPos?: number;
  // eqPos — position within the Equestrian page
  // (/us/en/category/equestrian/, 2026-11-16). The Equestrian
  // parent lists exactly those rows; the 5 clone equestrian rows
  // not on the live list carry no eqPos.
  eqPos?: number;
  // wRtwPos — position within the Women's Ready-to-Wear parent page
  // (/us/en/category/women/ready-to-wear/, 2026-11-16). The parent
  // lists exactly the 421 live tiles; the 217 clone rows not on the
  // live list carry no wRtwPos.
  wRtwPos?: number;
  // mRtwPos — position within the Men's Ready-to-Wear parent page
  // (/us/en/category/men/ready-to-wear/, 2026-11-16). The parent
  // lists exactly the 207 live tiles; the 6 clone rows not on the
  // live list carry no mRtwPos.
  mRtwPos?: number;
  // giftPos — position within the Gifts parent page
  // (/us/en/category/gifts/, 2026-11-16). The parent
  // lists exactly the 592 live tiles; the 6,216 clone rows not on the
  // live list carry no giftPos.
  giftPos?: number;
  // hairPos — position within the Women's Hair accessories page
  // (/us/en/category/women/hair-accessories/, 2026-11-16). The page
  // lists exactly the 26 live tiles; no other rows carry hairPos.
  hairPos?: number;
  // horsePos — position within the Equestrian Horse page
  // (/us/en/category/equestrian/horse/, 2026-11-17). The page
  // lists exactly the 50 live tiles; no other rows carry horsePos.
  horsePos?: number;
  // riderPos — position within the Equestrian Rider page
  // (/us/en/category/equestrian/rider/, 2026-11-17). The page
  // lists exactly the 103 live tiles; no other rows carry riderPos.
  riderPos?: number;
  bathPos?: number;
  wUniPos?: number;
  mUniPos?: number;
  hermPos?: number;
  lipsPos?: number;
  facePos?: number;
  eyesPos?: number;
  handsPos?: number;
  accPos?: number;
  mkPos?: number;
  frgViewPos?: number;
  charmPos?: number;
  travAccPos?: number;
  suitPos?: number;
  techPos?: number;
  furnPos?: number;
  twillyPos?: number;
  childPos?: number;
  balletPos?: number;
  wondersPos?: number;
  preciousPos?: number;
  casesPos?: number;
  officePos?: number;
  readingPos?: number;
  objectsPos?: number;
  textilesPos?: number;
  sportsPos?: number;
  beachPos?: number;
  collectionsPos?: number;
  chainedancrePos?: number;
  // Group 4 (2026-11-17) — Accessories 107 /
  // Luggage 48 / Women's Hats and gloves 115.
  leatherAccPos?: number;
  luggagePos?: number;
  wAccPos?: number;
  // Group 5 (2026-11-17) — Ties 488 / Men's scarves
  // 146 / Ties and scarves parent (first 40 of 634).
  tiePos?: number;
  menScarfPos?: number;
  menTiesPos?: number;
  timepiecePos?: number;
  petitHPos?: number;
  // Group 8 (2026-11-18) — Home and Art of living [1756]; first 40
  // tagged, positions 41..1756 pending the parent's live-browser read.
  homeArtPos?: number;
  giftWomenPos?: number;
  giftMenPos?: number;
  giftChildPos?: number;
  giftDogsPos?: number;
  watchWomenPos?: number;
  watchMenPos?: number; menJewPos?: number; tshirtPos?: number; knitPos?: number;
  bagsViewPos?: number;
};

export type Settings = {
  storeName: string; phone: string; heroTitle: string; heroText: string;
  shipTo: string; deliveryText: string; returnsText: string;
  paymentMethods: string; bgColor: string; serviceHours: string;
  logoMode: string; logoUrl: string;
  flagshipStore: string; shipToCountries: string; newsletterText: string;
  newsletterSuccess: string; copyrightText: string;
  serviceDeliveryBody: string; serviceReturnsBody: string;
  servicePaymentBody: string; chatEnabled: boolean; chatWelcome: string;
  legalLinksJson: string;
};
